// ============================================================
// LH UNIFORMES - CÓDIGO COMPLETO v6
// Catálogo: mostrar_catalogo = primera vez, catalogo_opcion = submenú
// ============================================================

const WorkflowStaticData = $getWorkflowStaticData('global');
const msg = $json.messages?.[0]?.text?.body?.trim() || "";
const msgLower = msg.toLowerCase().trim();
const telefono = $json.messages?.[0]?.from || "";

if (!msg || !telefono) return [];

const estadoActual = WorkflowStaticData[telefono] || "menu";
let pedido = WorkflowStaticData["pedido_" + telefono] || {};

// ============================================================
// PRECIOS
// ============================================================
const PRECIOS = {
  dama: {
    economico: {
      sencillo:  { "16":110000,"XS":115000,"S":115000,"M":120000,"L":120000,"XL":130000,"XXL":130000,"XXXL":150000 },
      camuflado: { "16":130000,"XS":135000,"S":135000,"M":140000,"L":140000,"XL":150000,"XXL":150000,"XXXL":170000 }
    },
    lafayette: {
      sencillo:  { "16":142000,"XS":142000,"S":142000,"M":147000,"L":155000,"XL":163000,"XXL":169000,"XXXL":183000 },
      camuflado: { "16":162000,"XS":162000,"S":162000,"M":167000,"L":175000,"XL":183000,"XXL":189000,"XXXL":203000 }
    },
    lotus:            { sencillo: { "16":208000,"XS":215000,"S":215000,"M":220000,"L":230000,"XL":238000,"XXL":244000,"XXXL":250000 } },
    microtec:         { sencillo: { "16":170000,"XS":170000,"S":170000,"M":178000,"L":185000,"XL":195000 } },
    unisangil:        { sencillo: { "16":142000,"XS":142000,"S":142000,"M":147000,"L":155000,"XL":163000,"XXL":169000,"XXXL":183000 } },
    psicologia_libre: { sencillo: { "16":147000,"XS":147000,"S":147000,"M":152000,"L":160000,"XL":168000,"XXL":174000,"XXXL":188000 } }
  },
  caballero: {
    lafayette: {
      sencillo:  { "S":158000,"M":166000,"L":176000,"XL":187000,"XXL":197000,"XXXL":205000 },
      camuflado: { "S":174000,"M":182000,"L":192000,"XL":203000,"XXL":213000,"XXXL":221000 }
    },
    lotus:            { sencillo: { "S":238000,"M":245000,"L":250000,"XL":260000,"XXL":268000,"XXXL":274000 } },
    unisangil:        { sencillo: { "S":158000,"M":166000,"L":176000,"XL":187000,"XXL":197000,"XXXL":205000 } },
    psicologia_libre: { sencillo: { "S":163000,"M":171000,"L":181000,"XL":192000,"XXL":202000,"XXXL":210000 } }
  },
  solo_blusa: {
    dama:      { "16":87000,"XS":87000,"S":87000,"M":90000,"L":94000,"XL":96000,"XXL":99000,"XXXL":103000 },
    caballero: { "16":93000,"XS":93000,"S":93000,"M":96000,"L":103000,"XL":106000,"XXL":110000,"XXXL":114000 }
  },
  solo_pantalon: {
    dama:      { "16":75000,"XS":75000,"S":75000,"M":77000,"L":81000,"XL":84000,"XXL":87000,"XXXL":94000 },
    caballero: { "16":83000,"XS":83000,"S":83000,"M":88000,"L":93000,"XL":97000,"XXL":103000,"XXXL":107000 }
  },
  filipina_dama: {
    basica:      { "16":87000,"XS":87000,"S":87000,"M":90000,"L":94000,"XL":96000,"XXL":99000 },
    cruzada:     { "16":99000,"XS":99000,"S":99000,"M":102000,"L":106000,"XL":108000,"XXL":111000 },
    manga_34:    { "16":120000,"XS":120000,"S":120000,"M":128000,"L":128000,"XL":134000 },
    manga_larga: { "16":120000,"XS":120000,"S":120000,"M":128000,"L":128000,"XL":134000 }
  },
  filipina_caballero: {
    basica:      { "S":93000,"M":96000,"L":103000,"XL":106000,"XXL":110000 },
    cruzada:     { "S":105000,"M":108000,"L":115000,"XL":118000,"XXL":122000 },
    manga_34:    { "S":128000,"M":134000,"L":140000,"XL":145000 },
    manga_larga: { "S":128000,"M":134000,"L":140000,"XL":145000 }
  },
  batas: {
    dama_unisangil:       { "16":120000,"XS":120000,"S":120000 },
    caballero_unisangil:  { "S":128000,"M":128000,"L":128000 },
    dama_psicologia:      { "16":126000,"XS":126000,"S":126000 },
    caballero_psicologia: { "S":134000,"M":134000,"L":134000 },
    dril:                 { "16":80000,"XS":80000,"S":80000,"M":80000 },
    antifluido_economico: { "16":80000,"XS":80000,"S":80000,"M":80000 },
    dacron_manga_corta:   { "16":45000,"S":45000,"M":48000,"L":48000 },
    dacron_manga_larga:   { "16":55000,"S":55000,"M":60000,"L":60000 }
  },
  gorros:    { antifluido_rigido: 25000 },
  delantales:{ antifluido_rigido: 35000 },
  polos:     { dama_caballero: 58000 }
};

// ============================================================
// UTILIDADES
// ============================================================
function formatPrecio(v) { return "$" + Math.round(v/1000) + ".000"; }

function getPrecio(categoria, subtipo, genero, talla) {
  try {
    if (categoria === "uniforme")           return PRECIOS[genero][subtipo].sencillo[talla] || null;
    if (categoria === "uniforme_camuflado") return PRECIOS[genero][subtipo].camuflado[talla] || null;
    if (categoria === "solo_blusa")         return PRECIOS.solo_blusa[genero][talla] || null;
    if (categoria === "solo_pantalon")      return PRECIOS.solo_pantalon[genero][talla] || null;
    if (categoria === "filipina_dama")      return PRECIOS.filipina_dama[subtipo][talla] || null;
    if (categoria === "filipina_caballero") return PRECIOS.filipina_caballero[subtipo][talla] || null;
    if (categoria === "bata")               return PRECIOS.batas[subtipo][talla] || null;
    if (categoria === "gorro")              return PRECIOS.gorros.antifluido_rigido;
    if (categoria === "delantal")           return PRECIOS.delantales.antifluido_rigido;
    if (categoria === "polo")               return PRECIOS.polos.dama_caballero;
  } catch(e) {}
  return null;
}

function resumenItem(item) {
  var l = [];
  l.push("📦 *Producto " + item.numero + ":*");
  l.push("• Categoría: " + item.categoriaLabel);
  if (item.codigo)        l.push("• Código: " + item.codigo);
  if (item.subtipoLabel)  l.push("• Tipo: " + item.subtipoLabel);
  if (item.genero)        l.push("• Género: " + item.genero);
  if (item.talla)         l.push("• Talla: " + item.talla);
  if (item.color)         l.push("• Color: " + item.color);
  if (item.camuflado !== undefined) l.push("• Pantalón camuflado: " + (item.camuflado ? "Sí" : "No"));
  if (item.bordadoLabel)  l.push("• Bordado: " + item.bordadoLabel);
  if (item.bordadoNombre) l.push("• Nombre a bordar: " + item.bordadoNombre);
  if (item.cantidad)      l.push("• Cantidad: " + item.cantidad);
  if (item.precio)        l.push("• Precio unitario: " + formatPrecio(item.precio));
  if (item.subtotal)      l.push("• Subtotal: " + formatPrecio(item.subtotal));
  return l.join("\n");
}

function resumenCompleto(p) {
  var t = "🧾 *RESUMEN DE PEDIDO - LH UNIFORMES*\n";
  t += "━━━━━━━━━━━━━━━━━━━━━\n";
  t += "👤 *Cliente:* " + p.nombre + "\n";
  t += "📱 *Celular:* " + p.celular + "\n";
  t += "━━━━━━━━━━━━━━━━━━━━━\n";
  (p.items || []).forEach(function(item) {
    t += resumenItem(item) + "\n";
    t += "━━━━━━━━━━━━━━━━━━━━━\n";
  });
  t += "💰 *TOTAL: " + formatPrecio(p.valorTotal) + "*\n";
  t += "💵 *Anticipo mínimo (50%): " + formatPrecio(p.anticipo) + "*\n";
  t += "📅 *Fecha:* " + new Date().toLocaleDateString('es-CO') + "\n";
  return t;
}

function guardar() { WorkflowStaticData["pedido_" + telefono] = pedido; }
function resetear() { WorkflowStaticData[telefono] = "menu"; delete WorkflowStaticData["pedido_" + telefono]; }
function ir(estado) { WorkflowStaticData[telefono] = estado; }
function salida(estado, extra) {
  var base = { mensaje: msg, telefono: telefono, estado: estado, pedido: pedido, indice: pedido.indice || 1 };
  if (extra) Object.keys(extra).forEach(function(k) { base[k] = extra[k]; });
  return [{ json: base }];
}

// ============================================================
// RESET GLOBAL
// ============================================================
if (msgLower === "menu" || msgLower === "0") {
  resetear();
  return [{ json: { mensaje: msg, telefono: telefono, estado: "menu", indice: 1 } }];
}

// ============================================================
// SALUDOS
// ============================================================
const saludos = ["hola","buenas","buenos días","buenos dias","buenas tardes","buenas noches","hi","hello","inicio","start","holi"];
if (estadoActual === "menu" && saludos.some(function(s){ return msgLower.startsWith(s); })) {
  resetear();
  return [{ json: { mensaje: msg, telefono: telefono, estado: "menu", indice: 1 } }];
}

// ============================================================
// MENÚ PRINCIPAL
// ============================================================
if (estadoActual === "menu") {
  if (msgLower === "1") {
    // Primera vez en catálogo: guarda estado "catalogo", manda "mostrar_catalogo"
    ir("catalogo");
    return [{ json: { mensaje: msg, telefono: telefono, estado: "mostrar_catalogo", indice: 1 } }];
  }
  if (msgLower === "2") { ir("precios");       return [{ json: { mensaje: msg, telefono: telefono, estado: "mostrar_precios",  indice: 1 } }]; }
  if (msgLower === "3") { ir("tallas_genero"); return [{ json: { mensaje: msg, telefono: telefono, estado: "tallas_genero",    indice: 1 } }]; }
  if (msgLower === "5") {
    pedido = { items: [], itemActual: {}, indice: 1 };
    guardar(); ir("pedido_nombre");
    return [{ json: { mensaje: msg, telefono: telefono, estado: "pedido_nombre", pedido: pedido, indice: 1 } }];
  }
  if (msgLower === "6") { ir("bordado_tipo"); return [{ json: { mensaje: msg, telefono: telefono, estado: "bordado_tipo",    indice: 1 } }]; }
  if (msgLower === "7") return [{ json: { mensaje: msg, telefono: telefono, estado: "buscar_en_sheets", busqueda: telefono, indice: 1 } }];
  if (msgLower === "8") { ir("asesor");       return [{ json: { mensaje: msg, telefono: telefono, estado: "mostrar_asesor", indice: 1 } }]; }
  return [{ json: { mensaje: msg, telefono: telefono, estado: "menu", indice: 1 } }];
}

// ============================================================
// CATÁLOGO — ya está dentro del catálogo
// Switch principal: "catalogo_opcion" → Switch1 filtra por subopcion
// Switch principal: "mostrar_catalogo" → muestra menú catálogo (solo primera vez)
// ============================================================
if (estadoActual === "catalogo") {
  if (msgLower === "0") {
    resetear();
    return [{ json: { mensaje: msg, telefono: telefono, estado: "menu", indice: 1 } }];
  }
  if (["1","2","3","4","5","6","7","8","9"].includes(msgLower)) {
    // Estado sigue "catalogo" en memoria
    // Manda estado DIFERENTE al Switch principal: "catalogo_opcion"
    // Switch1 filtra por subopcion
    return [{ json: { mensaje: msg, telefono: telefono, estado: "catalogo_opcion", subopcion: msgLower, indice: 1 } }];
  }
  // Cualquier otra cosa → repetir menú catálogo
  return [{ json: { mensaje: msg, telefono: telefono, estado: "mostrar_catalogo", indice: 1 } }];
}

// ============================================================
// PRECIOS
// ============================================================
if (estadoActual === "precios") {
  if (msgLower === "0") { resetear(); return [{ json: { mensaje: msg, telefono: telefono, estado: "menu", indice: 1 } }]; }
  return [{ json: { mensaje: msg, telefono: telefono, estado: "mostrar_precios", indice: 1 } }];
}

// ============================================================
// TALLAS
// ============================================================
if (estadoActual === "tallas_genero") {
  if (msgLower === "1") { resetear(); return [{ json: { mensaje: msg, telefono: telefono, estado: "tallas_dama",      indice: 1 } }]; }
  if (msgLower === "2") { resetear(); return [{ json: { mensaje: msg, telefono: telefono, estado: "tallas_caballero", indice: 1 } }]; }
  return [{ json: { mensaje: msg, telefono: telefono, estado: "tallas_genero", indice: 1 } }];
}

// ============================================================
// ASESOR Y BORDADOS
// ============================================================
if (estadoActual === "asesor") {
  return [{ json: { mensaje: msg, telefono: telefono, estado: "asesor", indice: 1 } }];
}
if (estadoActual === "bordado_tipo") {
  if (msgLower === "1") { resetear(); return [{ json: { mensaje: msg, telefono: telefono, estado: "bordado_nuevo",  indice: 1 } }]; }
  if (msgLower === "2") { ir("bordado_propio_foto"); return [{ json: { mensaje: msg, telefono: telefono, estado: "bordado_propio", indice: 1 } }]; }
  return [{ json: { mensaje: msg, telefono: telefono, estado: "bordado_tipo", indice: 1 } }];
}
if (estadoActual === "bordado_propio_foto") {
  resetear();
  return [{ json: { mensaje: msg, telefono: telefono, estado: "bordado_propio_texto", indice: 1 } }];
}

// ============================================================
// FLUJO DE PEDIDO
// ============================================================

if (estadoActual === "pedido_nombre") {
  if (msg.length < 2) return salida("pedido_nombre_error");
  pedido.nombre = msg;
  guardar(); ir("pedido_celular");
  return salida("pedido_celular");
}

if (estadoActual === "pedido_celular") {
  var cel = msg.replace(/[\s\-\(\)]/g, "");
  if (!/^\d{7,15}$/.test(cel)) return salida("pedido_celular_error");
  if (cel.startsWith("3") && cel.length === 10) cel = "57" + cel;
  pedido.celular = cel;
  guardar(); ir("pedido_categoria");
  return salida("pedido_categoria");
}

if (estadoActual === "pedido_categoria") {
  var cats = {
    "1": { key: "uniforme_completo", label: "Uniforme completo (blusa + pantalón)" },
    "2": { key: "solo_blusa",        label: "Solo blusa" },
    "3": { key: "solo_pantalon",     label: "Solo pantalón" },
    "4": { key: "filipina",          label: "Filipina" },
    "5": { key: "bata",              label: "Bata" },
    "6": { key: "polo",              label: "Polo" },
    "7": { key: "gorro",             label: "Gorro" },
    "8": { key: "delantal",          label: "Delantal" }
  };
  if (!cats[msgLower]) return salida("pedido_categoria");
  var indiceActual = pedido.indice || 1;
  pedido.itemActual = { numero: indiceActual, categoria: cats[msgLower].key, categoriaLabel: cats[msgLower].label };
  guardar();
  if (cats[msgLower].key === "uniforme_completo") { ir("pedido_codigo");           return salida("pedido_codigo"); }
  if (cats[msgLower].key === "solo_blusa" ||
      cats[msgLower].key === "solo_pantalon")      { ir("pedido_genero_simple");   return salida("pedido_genero_simple"); }
  if (cats[msgLower].key === "filipina")           { ir("pedido_filipina_genero"); return salida("pedido_filipina_genero"); }
  if (cats[msgLower].key === "bata")               { ir("pedido_bata_tipo");       return salida("pedido_bata_tipo"); }
  if (cats[msgLower].key === "polo")               { ir("pedido_polo_talla");      return salida("pedido_polo_talla"); }
  if (cats[msgLower].key === "gorro" || cats[msgLower].key === "delantal") {
    pedido.itemActual.subtipoLabel = "Antifluido Rígido";
    pedido.itemActual.precio = cats[msgLower].key === "gorro" ? PRECIOS.gorros.antifluido_rigido : PRECIOS.delantales.antifluido_rigido;
    guardar(); ir("pedido_cantidad_item");
    return salida("pedido_cantidad_item");
  }
  return salida("pedido_categoria");
}

if (estadoActual === "pedido_codigo") {
  pedido.itemActual.codigo = msg.toUpperCase();
  guardar(); ir("pedido_genero");
  return salida("pedido_genero");
}

if (estadoActual === "pedido_genero") {
  if (msgLower === "1" || msgLower === "dama")      { pedido.itemActual.genero = "dama";      guardar(); ir("pedido_tela_dama");      return salida("pedido_tela_dama"); }
  if (msgLower === "2" || msgLower === "caballero") { pedido.itemActual.genero = "caballero"; guardar(); ir("pedido_tela_caballero"); return salida("pedido_tela_caballero"); }
  return salida("pedido_genero");
}

if (estadoActual === "pedido_tela_dama") {
  var telasDama  = { "1":"economico","2":"lafayette","3":"lotus","4":"microtec","5":"unisangil","6":"psicologia_libre" };
  var labelsDama = { "1":"Económico Licrado","2":"Lafayette Rígido","3":"Lafayette Lotus","4":"Microtec","5":"Unisangil (Enfermería)","6":"Psicología Libre" };
  if (!telasDama[msgLower]) return salida("pedido_tela_dama");
  pedido.itemActual.subtipo = telasDama[msgLower];
  pedido.itemActual.subtipoLabel = labelsDama[msgLower];
  guardar();
  if (telasDama[msgLower] === "economico" || telasDama[msgLower] === "lafayette") { ir("pedido_camuflado"); return salida("pedido_camuflado"); }
  ir("pedido_talla"); return salida("pedido_talla");
}

if (estadoActual === "pedido_tela_caballero") {
  var telasCab  = { "1":"lafayette","2":"lotus","3":"unisangil","4":"psicologia_libre" };
  var labelsCab = { "1":"Lafayette Rígido","2":"Lafayette Lotus","3":"Unisangil (Enfermería)","4":"Psicología Libre" };
  if (!telasCab[msgLower]) return salida("pedido_tela_caballero");
  pedido.itemActual.subtipo = telasCab[msgLower];
  pedido.itemActual.subtipoLabel = labelsCab[msgLower];
  guardar();
  if (telasCab[msgLower] === "lafayette") { ir("pedido_camuflado"); return salida("pedido_camuflado"); }
  ir("pedido_talla"); return salida("pedido_talla");
}

if (estadoActual === "pedido_camuflado") {
  if (msgLower !== "si" && msgLower !== "sí" && msgLower !== "1" && msgLower !== "no" && msgLower !== "2") return salida("pedido_camuflado");
  pedido.itemActual.camuflado = (msgLower === "si" || msgLower === "sí" || msgLower === "1");
  guardar(); ir("pedido_talla"); return salida("pedido_talla");
}

if (estadoActual === "pedido_talla") {
  var tallasOk = ["16","XS","S","M","L","XL","XXL","XXXL"];
  var tu = msg.toUpperCase();
  if (!tallasOk.includes(tu)) return salida("pedido_talla_error");
  var item = pedido.itemActual;
  var precio = null;
  if (item.categoria === "uniforme_completo") precio = getPrecio(item.camuflado ? "uniforme_camuflado" : "uniforme", item.subtipo, item.genero, tu);
  else if (item.categoria === "solo_blusa")    precio = getPrecio("solo_blusa",   null, item.genero, tu);
  else if (item.categoria === "solo_pantalon") precio = getPrecio("solo_pantalon",null, item.genero, tu);
  else if (item.categoria === "filipina")      precio = getPrecio(item.genero === "dama" ? "filipina_dama" : "filipina_caballero", item.subtipo, null, tu);
  else if (item.categoria === "bata")          precio = getPrecio("bata", item.subtipo, null, tu);
  if (!precio) return salida("pedido_talla_no_disponible", { talla: tu });
  pedido.itemActual.talla = tu;
  pedido.itemActual.precio = precio;
  guardar(); ir("pedido_color"); return salida("pedido_color");
}

if (estadoActual === "pedido_genero_simple") {
  if (msgLower === "1" || msgLower === "dama")      { pedido.itemActual.genero = "dama";      guardar(); ir("pedido_talla"); return salida("pedido_talla"); }
  if (msgLower === "2" || msgLower === "caballero") { pedido.itemActual.genero = "caballero"; guardar(); ir("pedido_talla"); return salida("pedido_talla"); }
  return salida("pedido_genero_simple");
}

if (estadoActual === "pedido_filipina_genero") {
  if (msgLower === "1" || msgLower === "dama")      { pedido.itemActual.genero = "dama";      guardar(); ir("pedido_filipina_tipo"); return salida("pedido_filipina_tipo"); }
  if (msgLower === "2" || msgLower === "caballero") { pedido.itemActual.genero = "caballero"; guardar(); ir("pedido_filipina_tipo"); return salida("pedido_filipina_tipo"); }
  return salida("pedido_filipina_genero");
}

if (estadoActual === "pedido_filipina_tipo") {
  var tiposF  = { "1":"basica","2":"cruzada","3":"manga_34","4":"manga_larga" };
  var labelsF = { "1":"Básica","2":"Cruzada","3":"Manga 3/4","4":"Manga Larga" };
  if (!tiposF[msgLower]) return salida("pedido_filipina_tipo");
  pedido.itemActual.subtipo = tiposF[msgLower];
  pedido.itemActual.subtipoLabel = labelsF[msgLower];
  guardar(); ir("pedido_talla"); return salida("pedido_talla");
}

if (estadoActual === "pedido_bata_tipo") {
  var tiposB = {
    "1":{ key:"dama_unisangil",       label:"Dama Enfermería Unisangil" },
    "2":{ key:"caballero_unisangil",  label:"Caballero Enfermería Unisangil" },
    "3":{ key:"dama_psicologia",      label:"Dama Psicología UDI" },
    "4":{ key:"caballero_psicologia", label:"Caballero Psicología UDI" },
    "5":{ key:"dril",                 label:"Dril" },
    "6":{ key:"antifluido_economico", label:"Antifluido Económico" },
    "7":{ key:"dacron_manga_corta",   label:"Dacrón Manga Corta" },
    "8":{ key:"dacron_manga_larga",   label:"Dacrón Manga Larga" }
  };
  if (!tiposB[msgLower]) return salida("pedido_bata_tipo");
  pedido.itemActual.subtipo = tiposB[msgLower].key;
  pedido.itemActual.subtipoLabel = tiposB[msgLower].label;
  guardar(); ir("pedido_talla"); return salida("pedido_talla");
}

if (estadoActual === "pedido_polo_talla") {
  var tu2 = msg.toUpperCase();
  if (!["XS","S","M","L"].includes(tu2)) return salida("pedido_polo_talla_error");
  pedido.itemActual.talla = tu2;
  pedido.itemActual.precio = PRECIOS.polos.dama_caballero;
  pedido.itemActual.subtipoLabel = "Polo con bordado incluido";
  guardar(); ir("pedido_color"); return salida("pedido_color");
}

if (estadoActual === "pedido_color") {
  pedido.itemActual.color = msg;
  guardar(); ir("pedido_bordado"); return salida("pedido_bordado");
}

if (estadoActual === "pedido_bordado") {
  var esSi = (msgLower === "si" || msgLower === "sí" || msgLower === "1");
  var esNo = (msgLower === "no" || msgLower === "2");
  if (!esSi && !esNo) return salida("pedido_bordado");
  if (esSi) { pedido.itemActual.bordado = "si"; guardar(); ir("pedido_bordado_tipo"); return salida("pedido_bordado_tipo"); }
  pedido.itemActual.bordado = "no";
  pedido.itemActual.bordadoLabel = "Sin bordado";
  guardar(); ir("pedido_cantidad_item"); return salida("pedido_cantidad_item");
}

if (estadoActual === "pedido_bordado_tipo") {
  var tiposT  = { "1":"logo","2":"nombre","3":"ambos" };
  var labelsT = { "1":"Solo logo","2":"Solo nombre","3":"Logo + nombre" };
  if (!tiposT[msgLower]) return salida("pedido_bordado_tipo");
  pedido.itemActual.bordado = tiposT[msgLower];
  pedido.itemActual.bordadoLabel = labelsT[msgLower];
  guardar();
  if (tiposT[msgLower] === "logo") { ir("pedido_bordado_logo"); return salida("pedido_bordado_logo"); }
  ir("pedido_bordado_nombre_texto"); return salida("pedido_bordado_nombre_texto");
}

if (estadoActual === "pedido_bordado_logo") {
  pedido.itemActual.bordadoNota = "Logo: imagen enviada por WhatsApp";
  guardar();
  if (pedido.itemActual.bordado === "ambos") { ir("pedido_bordado_nombre_texto"); return salida("pedido_bordado_nombre_texto"); }
  ir("pedido_cantidad_item"); return salida("pedido_cantidad_item");
}

if (estadoActual === "pedido_bordado_nombre_texto") {
  pedido.itemActual.bordadoNombre = msg;
  guardar();
  if (pedido.itemActual.bordado === "ambos") { ir("pedido_bordado_logo"); return salida("pedido_bordado_logo_despues_nombre"); }
  ir("pedido_cantidad_item"); return salida("pedido_cantidad_item");
}

if (estadoActual === "pedido_cantidad_item") {
  var cant = parseInt(msg);
  if (isNaN(cant) || cant < 1) return salida("pedido_cantidad_item_error");
  pedido.itemActual.cantidad = cant;
  pedido.itemActual.subtotal = pedido.itemActual.precio * cant;
  var itemListo = JSON.parse(JSON.stringify(pedido.itemActual));
  pedido.items.push(itemListo);
  pedido.itemActual = {};
  guardar(); ir("pedido_otro_producto");
  return salida("pedido_otro_producto", { resumenItem: resumenItem(itemListo) });
}

if (estadoActual === "pedido_otro_producto") {
  if (msgLower === "si" || msgLower === "sí" || msgLower === "1") {
    pedido.indice = pedido.items.length + 1;
    pedido.itemActual = {};
    guardar(); ir("pedido_categoria");
    return salida("pedido_categoria");
  }
  if (msgLower === "no" || msgLower === "2") {
    pedido.valorTotal = pedido.items.reduce(function(s,i){ return s + i.subtotal; }, 0);
    pedido.anticipo = Math.ceil(pedido.valorTotal * 0.5);
    guardar(); ir("pedido_confirmar");
    return salida("pedido_confirmar", { resumen: resumenCompleto(pedido) });
  }
  return salida("pedido_otro_producto");
}

if (estadoActual === "pedido_confirmar") {
  if (msgLower === "si" || msgLower === "sí" || msgLower === "1") {
    var pf = JSON.parse(JSON.stringify(WorkflowStaticData["pedido_" + telefono]));
    pf.fecha = new Date().toLocaleDateString('es-CO');
    pf.resumenTexto = resumenCompleto(pf);
    resetear();
    return [{ json: { mensaje: msg, telefono: telefono, estado: "pedido_listo", pedido: pf, indice: 1 } }];
  }
  if (msgLower === "no" || msgLower === "2") {
    resetear();
    return [{ json: { mensaje: msg, telefono: telefono, estado: "pedido_cancelado", indice: 1 } }];
  }
  return salida("pedido_confirmar", { resumen: resumenCompleto(pedido) });
}

// ============================================================
// FALLBACK
// ============================================================
resetear();
return [{ json: { mensaje: msg, telefono: telefono, estado: "no_entendido", indice: 1 } }];

